from bisect import bisect_right


class Inventory:
    """On-hand and shipped totals per SKU, reservations by ID, and each SKU's on-hand history for look-backs."""

    def __init__(self):
        self.on_hand = {}
        self.shipped = {}
        self.res = {}                # id -> {"sku", "qty", "expires", "active"}
        self.res_count = 0
        self.history = {}            # sku -> [(timestamp, on hand or None)], in time order

    def _tick(self, ts):
        """Expire every reservation due at or before ts. O(r)."""
        for r in self.res.values():
            if r["active"] and r["expires"] <= ts:
                r["active"] = False

    def _record(self, ts, sku):
        self.history.setdefault(sku, []).append((ts, self.on_hand.get(sku)))

    def _available(self, sku):
        held = sum(r["qty"] for r in self.res.values() if r["active"] and r["sku"] == sku)
        return self.on_hand[sku] - held

    def add_product(self, timestamp, sku, quantity):
        self._tick(timestamp)
        if sku in self.on_hand:
            return False
        self.on_hand[sku], self.shipped[sku] = quantity, 0
        self._record(timestamp, sku)
        return True

    def restock(self, timestamp, sku, quantity):
        self._tick(timestamp)
        if sku not in self.on_hand:
            return None
        self.on_hand[sku] += quantity
        self._record(timestamp, sku)
        return self.on_hand[sku]

    def ship(self, timestamp, sku, quantity):
        self._tick(timestamp)
        if sku not in self.on_hand or quantity > self._available(sku):
            return None
        self.on_hand[sku] -= quantity
        self.shipped[sku] += quantity
        self._record(timestamp, sku)
        return self.on_hand[sku]

    def remove_product(self, timestamp, sku):
        self._tick(timestamp)
        if sku not in self.on_hand:
            return False
        del self.on_hand[sku], self.shipped[sku]
        for r in self.res.values():
            if r["active"] and r["sku"] == sku:
                r["active"] = False
        self._record(timestamp, sku)
        return True

    def top_shipped(self, timestamp, n):
        self._tick(timestamp)
        ranked = sorted(self.shipped.items(), key=lambda kv: (-kv[1], kv[0]))
        return [f"{s}({t})" for s, t in ranked[:n]]

    def low_stock(self, timestamp, threshold):
        self._tick(timestamp)
        rows = sorted((q, s) for s, q in self.on_hand.items() if q < threshold)
        return [f"{s}({q})" for q, s in rows]

    def reserve(self, timestamp, sku, quantity, ttl):
        self._tick(timestamp)
        if sku not in self.on_hand or quantity > self._available(sku):
            return None
        self.res_count += 1
        rid = f"res{self.res_count}"
        self.res[rid] = {"sku": sku, "qty": quantity, "expires": timestamp + ttl, "active": True}
        return rid

    def confirm(self, timestamp, reservation_id):
        self._tick(timestamp)
        r = self.res.get(reservation_id)
        if not r or not r["active"]:
            return False
        r["active"] = False
        self.on_hand[r["sku"]] -= r["qty"]
        self.shipped[r["sku"]] += r["qty"]
        self._record(timestamp, r["sku"])
        return True

    def get_available(self, timestamp, sku):
        self._tick(timestamp)
        return self._available(sku) if sku in self.on_hand else None

    def merge_products(self, timestamp, target_sku, source_sku):
        self._tick(timestamp)
        if target_sku == source_sku or target_sku not in self.on_hand or source_sku not in self.on_hand:
            return False
        self.on_hand[target_sku] += self.on_hand.pop(source_sku)
        self.shipped[target_sku] += self.shipped.pop(source_sku)
        for r in self.res.values():
            if r["active"] and r["sku"] == source_sku:
                r["sku"] = target_sku
        self._record(timestamp, target_sku)
        self._record(timestamp, source_sku)
        return True

    def get_on_hand_at(self, timestamp, sku, time_at):
        """O(log h): bisect over the SKU's history."""
        self._tick(timestamp)
        h = self.history.get(sku, [])
        i = bisect_right([t for t, _ in h], time_at)
        return h[i - 1][1] if i else None

