class Inventory {
  // On-hand and shipped totals per SKU, reservations by ID, and each SKU's on-hand history for look-backs.
  constructor() {
    this.onHand = new Map();
    this.shipped = new Map();
    this.res = new Map();        // id -> { sku, qty, expires, active }
    this.resCount = 0;
    this.history = new Map();    // sku -> [[timestamp, on hand or null]], in time order
  }

  tick(ts) {
    for (const r of this.res.values()) if (r.active && r.expires <= ts) r.active = false;
  }

  record(ts, sku) {
    if (!this.history.has(sku)) this.history.set(sku, []);
    this.history.get(sku).push([ts, this.onHand.has(sku) ? this.onHand.get(sku) : null]);
  }

  available(sku) {
    let held = 0;
    for (const r of this.res.values()) if (r.active && r.sku === sku) held += r.qty;
    return this.onHand.get(sku) - held;
  }

  addProduct(timestamp, sku, quantity) {
    this.tick(timestamp);
    if (this.onHand.has(sku)) return false;
    this.onHand.set(sku, quantity);
    this.shipped.set(sku, 0);
    this.record(timestamp, sku);
    return true;
  }

  restock(timestamp, sku, quantity) {
    this.tick(timestamp);
    if (!this.onHand.has(sku)) return null;
    this.onHand.set(sku, this.onHand.get(sku) + quantity);
    this.record(timestamp, sku);
    return this.onHand.get(sku);
  }

  ship(timestamp, sku, quantity) {
    this.tick(timestamp);
    if (!this.onHand.has(sku) || quantity > this.available(sku)) return null;
    this.onHand.set(sku, this.onHand.get(sku) - quantity);
    this.shipped.set(sku, this.shipped.get(sku) + quantity);
    this.record(timestamp, sku);
    return this.onHand.get(sku);
  }

  removeProduct(timestamp, sku) {
    this.tick(timestamp);
    if (!this.onHand.has(sku)) return false;
    this.onHand.delete(sku);
    this.shipped.delete(sku);
    for (const r of this.res.values()) if (r.active && r.sku === sku) r.active = false;
    this.record(timestamp, sku);
    return true;
  }

  topShipped(timestamp, n) {
    this.tick(timestamp);
    const byName = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
    return [...this.shipped.entries()].sort((a, b) => b[1] - a[1] || byName(a[0], b[0])).slice(0, n).map(([s, t]) => `${s}(${t})`);
  }

  lowStock(timestamp, threshold) {
    this.tick(timestamp);
    const byName = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
    return [...this.onHand.entries()].filter(([, q]) => q < threshold)
      .sort((a, b) => a[1] - b[1] || byName(a[0], b[0])).map(([s, q]) => `${s}(${q})`);
  }

  reserve(timestamp, sku, quantity, ttl) {
    this.tick(timestamp);
    if (!this.onHand.has(sku) || quantity > this.available(sku)) return null;
    this.resCount += 1;
    const id = `res${this.resCount}`;
    this.res.set(id, { sku, qty: quantity, expires: timestamp + ttl, active: true });
    return id;
  }

  confirm(timestamp, reservationId) {
    this.tick(timestamp);
    const r = this.res.get(reservationId);
    if (!r || !r.active) return false;
    r.active = false;
    this.onHand.set(r.sku, this.onHand.get(r.sku) - r.qty);
    this.shipped.set(r.sku, this.shipped.get(r.sku) + r.qty);
    this.record(timestamp, r.sku);
    return true;
  }

  getAvailable(timestamp, sku) {
    this.tick(timestamp);
    return this.onHand.has(sku) ? this.available(sku) : null;
  }

  mergeProducts(timestamp, targetSku, sourceSku) {
    this.tick(timestamp);
    if (targetSku === sourceSku || !this.onHand.has(targetSku) || !this.onHand.has(sourceSku)) return false;
    this.onHand.set(targetSku, this.onHand.get(targetSku) + this.onHand.get(sourceSku));
    this.onHand.delete(sourceSku);
    this.shipped.set(targetSku, this.shipped.get(targetSku) + this.shipped.get(sourceSku));
    this.shipped.delete(sourceSku);
    for (const r of this.res.values()) if (r.active && r.sku === sourceSku) r.sku = targetSku;
    this.record(timestamp, targetSku);
    this.record(timestamp, sourceSku);
    return true;
  }

  getOnHandAt(timestamp, sku, timeAt) {
    this.tick(timestamp);
    let v = null;
    for (const [t, q] of this.history.get(sku) || []) {
      if (t > timeAt) break;
      v = q;
    }
    return v;
  }
}
